#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

int main() {
    int n;
    if (scanf("%d", &n) != 1) {
        return 1;
    }

    if (n < 0) {
        printf("-1\n");
        return 0;
    }

    if (n == 0) {
        printf("0\n");
        return 0;
    }

    if (n == 1) {
        printf("1\n");
        return 0;
    }

    long long *fib = (long long *)malloc((n + 1) * sizeof(long long));
    if (fib == NULL) {
        return 1;
    }

    fib[0] = 0;
    fib[1] = 1;

    for (int i = 2; i <= n; i++) {
        fib[i] = fib[i - 1] + fib[i - 2];
    }

    printf("%lld\n", fib[n]);

    free(fib);
    return 0;
}
